def parse_line(line):
    name, qty, price = line.split(",")
    return {"name": name, "qty": int(qty), "price": float(price)}


def order_total(lines):
    total = 0
    for line in lines:
        item = parse_line(line)
        total += item["qty"] * item["price"]
    return total


lines = [
    "pen,2,1.50",
    "notebook,1,4.00",
    "stapler, 1 ,7.25",
    "",
]
print(f"total: {order_total(lines):.2f}")

def split_into_teams(players, team_count):
    teams = [[]] * team_count            # one empty list per team
    for i in range(1, len(players)):
        teams[i % team_count].append(players[i])
    return teams


players = ["Ana", "Ben", "Cy", "Dee", "Eli", "Fay"]
for number, team in enumerate(split_into_teams(players, 3), start=1):
    print(f"team {number}: {', '.join(team)}")

